+using System.Text.Json;
+using Microsoft.EntityFrameworkCore;
+using RecipeApi.Models;
+
+namespace RecipeApi.Services;
+
+public sealed partial class RecipeFilePublicationStore
+{
+    // Re-reading a retained PDF is distinct from importing fresh bytes. Authority
+    // comes from its accepted original conversion and the current accepted report.
+    internal async Task<bool> CanRepairCanonicalPdfAsync(RecipePublicationCapture capture, Guid operationId, CancellationToken ct)
+    {
+        if (capture.FieldHashVersion != 4 || capture.Fields is not { CanonicalContent: not null, RawMetadata: not null, SourceUrl: null }
+            || capture.Fields.ImageCount is < 1 or > 10
+            || capture.Files.GetValueOrDefault("original/source.pdf") is not { Length: > 0 }
+            || capture.Files.GetValueOrDefault("original/content.html") is not null) return false;
+        var task = await db.WorkflowTasks.AsNoTracking().SingleOrDefaultAsync(x => x.TaskId == operationId, ct);
+        if (task is null || task.InstanceId == Guid.Empty || task.ProcessorName is not ("ConvertPdf" or "ExtractRecipe")) return false;
+        var workflow = await db.WorkflowInstances.AsNoTracking().Include(x => x.Tasks).SingleOrDefaultAsync(x => x.Id == task.InstanceId, ct);
+        var report = await db.RecipeImportReports.AsNoTracking().SingleOrDefaultAsync(x => x.RecipeId == capture.RecipeId, ct);
+        if (workflow?.WorkflowId != "recipe-import" || workflow.RecipePublicationCapture is null
+            || report?.RepairIntentId is not Guid intentId || report.LastWorkflowInstanceId != workflow.Id
+            || report.Status != RecipeImportReportStatus.Reimporting || !report.Reasons.SequenceEqual(["ingredients"])
+            || string.IsNullOrWhiteSpace(report.Note)) return false;
+        var intent = await db.RecipeRepairIntents.AsNoTracking().SingleOrDefaultAsync(x => x.Id == intentId, ct)
+            ?? throw new InvalidDataException("Accepted PDF repair command is missing.");
+        RecipeReportRepairIntent.ValidateAccepted(intent, workflow);
+        ValidateExecutionLaunch(workflow);
+        var command = RecipeReportRepairIntent.Read(intent);
+        if (!command.Parameters.TryGetValue("repairReasons", out var reasons) || reasons != string.Join(',', report.Reasons)
+            || !command.Parameters.TryGetValue("repairNote", out var note) || note != report.Note) return false;
+        var launch = ReadRecoveryJson<Launch>(workflow.RecipePublicationCapture);
+        if (launch.Capture.RecipeId != capture.RecipeId || launch.Capture.FieldHashVersion != 4
+            || launch.Capture.FieldHash != capture.FieldHash || launch.Capture.SourceRevision != capture.SourceRevision
+            || launch.Capture.ContentRevision != capture.ContentRevision || !SameFiles(launch.Capture.Files, capture.Files)
+            || Hash(launch.Capture.FoodAuthority!) != Hash(capture.FoodAuthority!)
+            || !launch.Tasks.TryGetValue(operationId, out var original) || original.Processor != task.ProcessorName
+            || original.Payload != CanonicalRecipeContentStore.NormalizeJson(task.Payload)) return false;
+        if (!await HasOriginalPdfPagesAsync(capture, ct)) return false;
+        if (task.ProcessorName == "ConvertPdf") return true;
+        // The current repair extraction must also descend from its own delivered
+        // page-reuse decision. An older converter alone cannot admit extraction.
+        var converter = workflow.Tasks.SingleOrDefault(x => x.ProcessorName == "ConvertPdf");
+        if (converter is null || !original.DependsOn.Contains(converter.TaskName, StringComparer.Ordinal)) return false;
+        var publication = await db.RecipeFilePublications.AsNoTracking().SingleOrDefaultAsync(x => x.RecipeId == capture.RecipeId && x.OperationId == converter.TaskId, ct);
+        if (publication is not { Delivered: true } || converter.Result is null) return false;
+        var envelope = ReadEnvelope(publication);
+        if (envelope.Candidate.SourceKind != "pdf-repair-pages" || envelope.Capture.FieldHash != capture.FieldHash
+            || !SameFiles(envelope.Capture.Files, capture.Files)) return false;
+        ValidateRecoveryPublicationChain(workflow, new Dictionary<Guid, RecipeFilePublication> { [converter.TaskId] = publication });
+        return Processors.PdfConversionProcessor.ValidateOriginalHistory(converter.Payload, converter.Result, [publication]) == capture.RecipeId;
+    }
+
+    private async Task<bool> HasOriginalPdfPagesAsync(RecipePublicationCapture current, CancellationToken ct)
+    {
+        var records = await db.RecipeFilePublications.AsNoTracking().Where(x => x.RecipeId == current.RecipeId).ToListAsync(ct);
+        var origins = records.Where(x => x.Delivered && ReadEnvelope(x).Candidate is { SourceKind: "bootstrap", FollowupIntent: not null }
+            && ReadEnvelope(x).Candidate.SourceFiles?.ContainsKey("original/source.pdf") == true).ToArray();
+        var matches = 0;
+        foreach (var bootstrap in origins)
+        {
+            var workflow = await db.WorkflowInstances.AsNoTracking().Include(x => x.Tasks).SingleOrDefaultAsync(x => x.Id == bootstrap.OperationId, ct);
+            if (workflow?.WorkflowId != "recipe-import" || workflow.RecipePublicationCapture is null) continue;
+            ValidateExecutionLaunch(workflow);
+            var launch = ReadRecoveryJson<Launch>(workflow.RecipePublicationCapture);
+            var extraction = workflow.Tasks.SingleOrDefault(x => x.ProcessorName == "ExtractRecipe");
+            if (launch.Capture.RecipeId != current.RecipeId || extraction is null
+                || bootstrap.ResultHash != launch.Capture.FieldHash || !await HasFreshSourceAncestryAsync(workflow, launch, extraction.TaskId, ct)) continue;
+            var source = ReadEnvelope(bootstrap).Candidate.SourceFiles!;
+            if (!Equal(source["original/source.pdf"], current.Files.GetValueOrDefault("original/source.pdf"))) continue;
+            var converter = workflow.Tasks.Single(x => x.ProcessorName == "ConvertPdf");
+            var conversion = records.Single(x => x.OperationId == converter.TaskId);
+            var envelope = ReadEnvelope(conversion);
+            if (envelope.Candidate.SourceKind != "pdf" || envelope.Candidate.SourceFiles?.Count != 40
+                || envelope.Candidate.Info.ImageCount != current.Fields!.ImageCount) continue;
+            var pagesMatch = true;
+            for (var index = 0; index < 20; index++)
+                foreach (var extension in new[] { ".jpg", ".jpeg", ".png", ".webp" })
+                {
+                    var path = $"original/{index}{extension}";
+                    if (!Equal(envelope.Output.GetValueOrDefault(path), current.Files.GetValueOrDefault(path))) pagesMatch = false;
+                }
+            if (pagesMatch) matches++;
+        }
+        return matches == 1;
+    }
+
+    private static IReadOnlyDictionary<string, byte[]?> PreparePdfRepairPages(RecipePublicationCapture capture, RecipePublicationCandidate candidate)
+    {
+        if (capture.FieldHashVersion != 4 || capture.Fields?.CanonicalContent is null || candidate.RecipeJson is not null
+            || candidate.SourceFiles is not { Count: 0 } || candidate.SourceContext is not null
+            || candidate.BootstrapIntent is not null || candidate.FollowupIntent is not null || candidate.ReviewReasons is not null
+            || candidate.MappingEvidence is not null || capture.Files.GetValueOrDefault("recipe.info") is not { } bytes
+            || Hash(JsonSerializer.Deserialize<RecipeInfo>(bytes, Json)!) != Hash(candidate.Info))
+            throw new InvalidDataException("PDF repair page reuse cannot select source, media, or metadata.");
+        return new Dictionary<string, byte[]?>();
+    }
+}
