+        task.Status = RecipeApi.Models.TaskStatus.Processing;
+        await db.SaveChangesAsync();
+        var result = await execute();
+        var returned = JsonSerializer.Serialize(result, JsonDefaults.CamelCase);
+        task.Result = returned;
+        task.Status = RecipeApi.Models.TaskStatus.Completed;
+        await (Task)history.GetMethod("ObserveAsync", BindingFlags.Public | BindingFlags.Static)!.Invoke(null,
+            [db, attempt, task, "succeeded", true, returned, clock.UtcNow, CancellationToken.None])!;
+        await db.SaveChangesAsync();
+        history.GetMethod("Validate", BindingFlags.Public | BindingFlags.Static)!.Invoke(null, [attempt]);
+    }
